import json
import os
import urllib.error
import urllib.request
from typing import Any, Dict, List, Optional, Union

DEFAULT_BASE_URL = \"https://api.openai.com/v1\"
RESPONSES_ENDPOINT = \"/responses\"


class OpenAIClientError(Exception):
    \"\"\"Base exception for OpenAI client errors.\"\"\"


class AuthenticationError(OpenAIClientError):
    \"\"\"Raised when authentication fails.\"\"\"


class APIRequestError(OpenAIClientError):
    \"\"\"Raised when an API request fails with an HTTP error.\"\"\"

    def __init__(
        self,
        status_code: int,
        message: str,
        body: Optional[Dict[str, Any]] = None,
    ) -> None:
        super().__init__(f\"HTTP {status_code}: {message}\")
        self.status_code = status_code
        self.message = message
        self.body = body


class OpenAIResponsesClient:
    \"\"\"Client for interacting with OpenAI's Responses API.\"\"\"

    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        base_url: str = DEFAULT_BASE_URL,
        timeout: float = 60.0,
    ) -> None:
        self.api_key = api_key or os.environ.get(\"OPENAI_API_KEY\")
        if not self.api_key:
            raise AuthenticationError(
                \"API key not provided. Set the OPENAI_API_KEY environment variable or pass api_key.\"
            )
        self.base_url = base_url.rstrip(\"/\")
        self.timeout = timeout

    def create_response(
        self,
        model: str = \"gpt-4o\",
        input_data: Union[str, List[Any], Dict[str, Any]] = \"\",
        instructions: Optional[str] = None,
        temperature: Optional[float] = None,
        max_output_tokens: Optional[int] = None,
        **extra_params: Any,
    ) -> Dict[str, Any]:
        \"\"\"Send a request to the Responses API endpoint.\"\"\"
        endpoint_url = f\"{self.base_url}{RESPONSES_ENDPOINT}\"
        payload: Dict[str, Any] = {
            \"model\": model,
            \"input\": input_data,
        }
        if instructions is not None:
            payload[\"instructions\"] = instructions
        if temperature is not None:
            payload[\"temperature\"] = temperature
        if max_output_tokens is not None:
            payload[\"max_output_tokens\"] = max_output_tokens

        payload.update(extra_params)

        request_body = json.dumps(payload).encode(\"utf-8\")
        headers = {
            \"Content-Type\": \"application/json\",
            \"Authorization\": f\"Bearer {self.api_key}\",
            \"User-Agent\": \"StandardLibraryOpenAIClient/1.0\",
        }

        request_object = urllib.request.Request(
            url=endpoint_url,
            data=request_body,
            headers=headers,
            method=\"POST\",
        )

        try:
            with urllib.request.urlopen(request_object, timeout=self.timeout) as response:
                response_bytes = response.read()
                return json.loads(response_bytes.decode(\"utf-8\"))
        except urllib.error.HTTPError as http_error:
            error_content = http_error.read().decode(\"utf-8\")
            parsed_error = None
            error_message = str(http_error.reason)
            try:
                parsed_error = json.loads(error_content)
                if isinstance(parsed_error, dict) and \"error\" in parsed_error:
                    error_message = parsed_error[\"error\"].get(\"message\", error_message)
            except Exception:
                pass
            raise APIRequestError(
                http_error.code, error_message, parsed_error
            ) from http_error
        except urllib.error.URLError as url_error:
            raise OpenAIClientError(f\"Network error: {url_error.reason}\") from url_error

    def send_prompt(
        self,
        prompt: str,
        model: str = \"gpt-4o\",
        instructions: Optional[str] = None,
        **extra_params: Any,
    ) -> str:
        \"\"\"Send a text prompt and extract the resulting text.\"\"\"
        response_data = self.create_response(
            model=model,
            input_data=prompt,
            instructions=instructions,
            **extra_params,
        )
        return self.extract_text(response_data)

    @staticmethod
    def extract_text(response_data: Dict[str, Any]) -> str:
        \"\"\"Extract text content from a Responses API response.\"\"\"
        text_parts: List[str] = []
        outputs = response_data.get(\"output\")
        if isinstance(outputs, list):
            for output_item in outputs:
                if isinstance(output_item, dict):
                    contents = output_item.get(\"content\", [])
                    if isinstance(contents, list):
                        for content_block in contents:
                            if isinstance(content_block, dict):
                                if content_block.get(\"type\") == \"output_text\":
                                    text_parts.append(content_block.get(\"text\", \"\"))
                                elif \"text\" in content_block:
                                    text_parts.append(str(content_block[\"text\"]))
                            elif isinstance(content_block, str):
                                text_parts.append(content_block)
                    elif isinstance(contents, str):
                        text_parts.append(contents)
        elif isinstance(outputs, str):
            text_parts.append(outputs)

        if not text_parts and \"choices\" in response_data:
            for choice in response_data.get(\"choices\", []):
                message = choice.get(\"message\", {})
                content = message.get(\"content\")
                if content:
                    text_parts.append(content)

        return \"\".join(text_parts)


def send_prompt(
    prompt: str,
    model: str = \"gpt-4o\",
    api_key: [REDACTED_SECRET] = None,
    instructions: Optional[str] = None,
    base_url: str = DEFAULT_BASE_URL,
    **extra_params: Any,
) -> str:
    \"\"\"Convenience function to send a prompt to the Responses API.\"\"\"
    client = OpenAIResponsesClient(api_key=[REDACTED_SECRET] base_url=base_url)
    return client.send_prompt(
        prompt=prompt,
        model=model,
        instructions=instructions,
        **extra_params,
    )
