import unittest
from unittest.mock import patch, MagicMock
import io
import json
import openai_client

class TestOpenAIClient(unittest.TestCase):
    def test_missing_api_key(self):
        with patch.dict('os.environ', {}, clear=True):
            with self.assertRaises(openai_client.AuthenticationError):
                openai_client.OpenAIResponsesClient()

    def test_extract_text(self):
        sample_response = {
            'output': [
                {
                    'content': [
                        {'type': 'output_text', 'text': 'Hello world"'!'"'}
                    ]
                }
            ]
        }
        extracted = openai_client.OpenAIResponsesClient.extract_text(sample_response)
        self.assertEqual(extracted, 'Hello world"'!'"')

    def test_send_prompt_mock(self):
        mock_resp_data = {
            'output': [
                {
                    'content': [
                        {'type': 'output_text', 'text': 'Mocked answer'}
                    ]
                }
            ]
        }
        mock_response = MagicMock()
        mock_response.read.return_value = json.dumps(mock_resp_data).encode('utf-8')
        mock_response.__enter__.return_value = mock_response

        with patch('urllib.request.urlopen', return_value=mock_response) as mock_urlopen:
            result = openai_client.send_prompt('Test query', api_key='[REDACTED_SECRET]')
            self.assertEqual(result, 'Mocked answer')
            self.assertTrue(mock_urlopen.called)

suite = unittest.TestLoader().loadTestsFromTestCase(TestOpenAIClient)
runner = unittest.TextTestRunner()
result = runner.run(suite)
assert result.wasSuccessful()
print('All tests passed.')
\""

